<?php
 namespace Pterodactyl\Models\Dezerx; use Pterodactyl\Models\User; use Pterodactyl\Models\Model; use Pterodactyl\Models\Server; use Illuminate\Database\Eloquent\Relations\BelongsTo; class RecycledFile extends Model { public const RESOURCE_NAME = 'recycled_file'; protected $table = 'dezerx_recycled_files'; protected $guarded = ['id']; protected $casts = [ 'server_id' => 'int', 'user_id' => 'int', 'is_directory' => 'bool', 'size' => 'int', 'deleted_at' => 'datetime', 'expires_at' => 'datetime', ]; public static array $validationRules = [ 'server_id' => 'required|int|exists:servers,id', 'root' => 'required|string', 'name' => 'required|string', 'stored_name' => 'required|string', ]; public function originalPath(): string { return rtrim($this->root, '/') . '/' . $this->name; } public function server(): BelongsTo { return $this->belongsTo(Server::class); } public function user(): BelongsTo { return $this->belongsTo(User::class); } } 